  getIdState(state: string) {
    if (state == "Aprobado" || state == "Completo") {
      this.stateCicChanged.emit(4);
      localStorage.setItem("cicState", "Aprobada");
      this.mensajeServicio.storageSub.next('changed');
    } else if (state == "Rechazado") {
      this.stateCicChanged.emit(3);
      localStorage.setItem("cicState", "Rechazado");
      this.mensajeServicio.storageSub.next('changed');
    } else if (state == "Por aprobar" || state == "Incompleto") {
      this.stateCicChanged.emit(2);
      localStorage.setItem("cicState", "Poraprobar");
      this.mensajeServicio.storageSub.next('changed');
    } else {
      this.stateCicChanged.emit(1);
      localStorage.setItem("cicState", "Pendiente");
      this.mensajeServicio.storageSub.next('changed');
    }
  }
